package net.civeira.phylax.features.oauth.mfa.domain.gateway;

/**
 * Atomic consumption of an MFA recovery code (PHP 039): of two concurrent uses of the same code
 * only one wins.
 */
public interface RecoveryCodeConsumptionGateway {

  /**
   * Marks a recovery code as used if it was still unused.
   *
   * @param codeUid recovery code identifier
   * @param userUid owner of the code
   * @return true for the request that consumed it, false when it was already used
   */
  boolean consume(String codeUid, String userUid);
}
